import { ElDialog, ElForm, ElFormItem, ElInput, ElSelect, ElOption, ElButton, ElMessage } from 'element-plus';
import { ref } from 'vue';
import axios from 'axios';
import DockerNetworks from "@/components/Network/DockerNetworks.vue";

// 弹出框显示状态

export default {
  __name: 'AddContainerDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);

    // 打开弹出框
    const openDialog = () => {
      dialogVisible.value = true;
    };

    // 容器数据
    const container = ref({
      image: '',
      name: '',
      networks: []
    });

    // 提交容器数据
    const submitAdd = async () => {
      try {
        await axios.post('http://localhost:8081/container/create', container.value);
        dialogVisible.value = false;
        ElMessage.success('容器添加成功');
      } catch (error) {
        console.error('Error creating container:', error.response || error);
        ElMessage.error('容器添加失败');
      }
    };
    __expose({
      openDialog
    });
    const __returned__ = {
      dialogVisible,
      openDialog,
      container,
      submitAdd,
      get ElDialog() {
        return ElDialog;
      },
      get ElForm() {
        return ElForm;
      },
      get ElFormItem() {
        return ElFormItem;
      },
      get ElInput() {
        return ElInput;
      },
      get ElSelect() {
        return ElSelect;
      },
      get ElOption() {
        return ElOption;
      },
      get ElButton() {
        return ElButton;
      },
      get ElMessage() {
        return ElMessage;
      },
      ref,
      get axios() {
        return axios;
      },
      DockerNetworks
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
